export const getBoundingClientRect = (el, zoom = 1) => {
  let {
    top,
    right,
    bottom,
    left,
    width,
    height,
    x,
    y
  } = el.getBoundingClientRect();
  width /= zoom;
  height /= zoom;
  x /= zoom;
  y /= zoom;
  top /= zoom;
  right /= zoom;
  bottom /= zoom;
  left /= zoom;
  const style = getComputedStyle(el);
  const transformMatrix = style.getPropertyValue('transform');
  if (transformMatrix && el instanceof HTMLElement) {
    if (transformMatrix.startsWith('matrix(')) {
      const ta = transformMatrix.slice(7, -1).split(/, /);
      const scaleX = +ta[0];
      const scaleY = +ta[3];
      const dx = +ta[4];
      const dy = +ta[5];
      const transformOrigin = style.getPropertyValue('transform-origin');
      const updatedX = x - dx - (1 - scaleX) * parseFloat(transformOrigin);
      const updatedY = y - dy - (1 - scaleY) * parseFloat(transformOrigin.slice(transformOrigin.indexOf(' ') + 1));
      const updatedWidth = scaleX ? width / scaleX : el.offsetWidth;
      const updatedHeight = scaleY ? height / scaleY : el.offsetHeight;
      return {
        top: updatedY,
        right: updatedX + updatedWidth,
        bottom: updatedY + updatedHeight,
        left: updatedX,
        width: updatedWidth,
        height: updatedHeight,
        x: updatedX,
        y: updatedY
      };
    }
    return {
      top,
      right,
      bottom,
      left,
      width,
      height,
      x,
      y
    };
  }
  return {
    top,
    right,
    bottom,
    left,
    width,
    height,
    x,
    y
  };
};