import { layers } from '../../constants';
export const extractZIndex = zIndex => {
  switch (typeof zIndex) {
    case 'number':
    case 'undefined':
      {
        return zIndex;
      }
    case 'string':
      {
        return zIndex in layers ? layers[zIndex] : zIndex;
      }
    default:
      {
        return undefined;
      }
  }
};